def download_file_with_human_behavior(url: str, dest_path: str, progress_callback=None, log_callback=None) -> bool:
    """Download file with human-like behavior to avoid anti-bot detection"""
    try:
        headers = {
            'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36',
            'Accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,image/webp,*/*;q=0.8',
            'Accept-Language': 'en-US,en;q=0.5',
            'Connection': 'keep-alive',
            'Upgrade-Insecure-Requests': '1',
        }

        time.sleep(0.5 + (time.time() % 2))

        req = urllib.request.Request(url, headers=headers)

        with urllib.request.urlopen(req) as response:
            total_size = int(response.headers.get('content-length', 0))
            downloaded = 0
            chunk_size = 8192

            with open(dest_path, 'wb') as f:
                while True:
                    chunk = response.read(chunk_size)
                    if not chunk:
                        break
                    f.write(chunk)
                    downloaded += len(chunk)

                    if progress_callback and total_size > 0:
                        progress = int((downloaded / total_size) * 100)
                        progress_callback(progress)

                    time.sleep(0.01 + (time.time() % 0.05))

        if log_callback:
            log_callback(f"Downloaded {os.path.basename(dest_path)} ({downloaded:,} bytes)", 'info')
        return True
    except urllib.error.HTTPError as e:
        if log_callback:
            log_callback(f"HTTP Error {e.code}: {e.reason}", 'error')
        if log_callback:
            log_callback(f"Download failed: HTTP Error {e.code}: {e.reason}", 'error')
        return False
    except Exception as e:
        if log_callback:
            log_callback(f"Download failed: {e}", 'error')
        return False

def extract_archive(archive_path: str, extract_to: str, extract_type: str, log_callback=None) -> bool:
    """Extract various archive types"""
    try:
        ensure_dir(extract_to)

        if extract_type == 'zip':
            with zipfile.ZipFile(archive_path, 'r') as zip_ref:
                safe_extract_zip(zip_ref, extract_to)
            if log_callback:
                log_callback(f"Extracted zip to {extract_to}", 'info')
            return True

        elif extract_type == 'zip_nested':
            temp_dir = tempfile.mkdtemp()
            try:
                with zipfile.ZipFile(archive_path, 'r') as zip_ref:
                    safe_extract_zip(zip_ref, temp_dir)

                for root, dirs, files in os.walk(temp_dir):
                    for f in files:
                        src = os.path.join(root, f)
                        rel_path = os.path.relpath(src, temp_dir)
                        dst = os.path.join(extract_to, rel_path)
                        ensure_dir(os.path.dirname(dst))
                        shutil.copy2(src, dst)

                if log_callback:
                    log_callback(f"Extracted nested zip contents to {extract_to}", 'info')
                return True
            finally:
                shutil.rmtree(temp_dir, ignore_errors=True)

        elif extract_type in ['exe', 'jar']:
            filename = os.path.basename(archive_path)
            dest_path = os.path.join(extract_to, filename)
            shutil.copy2(archive_path, dest_path)
            if log_callback:
                log_callback(f"Copied {filename} to {extract_to}", 'info')
            return True

        elif extract_type == 'none':
            return True

        return False
    except zipfile.BadZipFile as e:
        if log_callback:
            log_callback(f"Extraction failed: File is not a valid zip - {e}", 'error')
        return False
    except Exception as e:
        if log_callback:
            log_callback(f"Extraction failed: {e}", 'error')
        return False

def move_files_to_subdir(src_dir: str, tool_subdir_name: str, expected_files: List[str], log_callback=None) -> bool:
    """Move expected files to their proper subdirectories"""
    try:
        tool_subdir = os.path.join(TOOLS_DIR, tool_subdir_name)
        ensure_dir(tool_subdir)

        found_files = []
        missing_files = []

        for expected_file in expected_files:
            expected_normalized = expected_file.replace('/', os.sep).replace('\\', os.sep)

            found = False
            for root, dirs, files in os.walk(src_dir):
                for f in files:
                    file_rel_path = os.path.relpath(os.path.join(root, f), src_dir).replace('/', os.sep).replace('\\', os.sep)
                    if file_rel_path == expected_normalized or f == os.path.basename(expected_file):
                        src_file = os.path.join(root, f)

                        dest_basename = os.path.basename(expected_file)
                        dest_file = os.path.join(tool_subdir, dest_basename)
                        shutil.copy2(src_file, dest_file)
                        found_files.append(dest_basename)
                        found = True
                        if log_callback:
                            log_callback(f"Found and copied {dest_basename}", 'info')
                        break
                if found:
                    break

            if not found:
                missing_files.append(expected_file)
                if log_callback:
                    log_callback(f"Could not find: {expected_file}", 'warning')

        if missing_files and not found_files:
            if log_callback:
                log_callback(f"No files found for {tool_subdir_name}", 'error')
            return False

        return True
    except Exception as e:
        if log_callback:
            log_callback(f"File moving failed: {e}", 'error')
        return False

def cleanup_tool_dir(tool_name: str, log_callback=None) -> bool:
    """Clean up a tool's directory before re-installation"""
    metadata = TOOL_METADATA.get(tool_name, {})
    tool_subdir = metadata.get('subdir', tool_name)
    tool_dir = os.path.join(TOOLS_DIR, tool_subdir)

    if os.path.exists(tool_dir):
        try:
            shutil.rmtree(tool_dir, ignore_errors=True)
            if log_callback:
                log_callback(f"Cleaned up {tool_dir}", 'info')
        except Exception as e:
            if log_callback:
                log_callback(f"Failed to clean {tool_dir}: {e}", 'warning')

    ensure_dir(TOOLS_DIR)
    ensure_dir(tool_dir)
    return True

def cleanup_temp_files(temp_dir: str):
    """Clean up temporary files and directories"""
    try:
        if os.path.exists(temp_dir):
            shutil.rmtree(temp_dir, ignore_errors=True)
    except Exception as e:
        print(f"Cleanup failed: {e}")

def download_and_setup_tool(tool_name: str, progress_callback=None, log_callback=None) -> bool:
    """Download, extract, and setup a single tool"""
    if tool_name not in TOOL_METADATA:
        if log_callback:
            log_callback(f"Unknown tool: {tool_name}", 'error')
        return False

    metadata = TOOL_METADATA[tool_name]

    if metadata['url'] == 'local':
        if log_callback:
            log_callback(f"Verifying local tool {tool_name}...", 'info')
        tool_dir = os.path.join(TOOLS_DIR, metadata['subdir'])
        expected_files = metadata['expected_files']
        missing = []
        for ef in expected_files:
            ef_path = os.path.join(tool_dir, ef)
            if not os.path.exists(ef_path):
                missing.append(ef)
        if missing:
            if log_callback:
                log_callback(f"Local tool {tool_name} missing files: {', '.join(missing)}", 'warning')
            return False
        if log_callback:
            log_callback(f"[Ok] {tool_name} verified (local)", 'success')
        return True

    temp_dir = tempfile.mkdtemp(prefix=f"{tool_name}_download_")

    try:
        cleanup_tool_dir(tool_name, log_callback)

        if log_callback:
            log_callback(f"Downloading {tool_name} v{metadata['version']}...", 'info')

        download_url = metadata['url']
        if download_url.rstrip('/').endswith('/releases'):
            if log_callback:
                log_callback(
                    f"No direct release asset URL is configured for {tool_name}; "
                    "use the AIK bundle or install this tool separately.",
                    'warning',
                )
            return False

        archive_name = metadata.get('filename') or os.path.basename(download_url)
        archive_path = os.path.join(temp_dir, archive_name)
        download_urls = [download_url]
        if 'sourceforge.net/projects/' in download_url and download_url.endswith('/download'):
            direct_url = download_url.replace(
                'https://sourceforge.net/projects/',
                'https://downloads.sourceforge.net/project/',
            ).removesuffix('/download')
            download_urls.append(direct_url)

        downloaded = False
        for candidate_url in download_urls:
            if download_file_with_human_behavior(candidate_url, archive_path, progress_callback, log_callback):
                downloaded = True
                break
        if not downloaded:
            if log_callback:
                log_callback(f"Failed to download {tool_name}", 'error')
            return False

        if log_callback:
            log_callback(f"Extracting {tool_name}...", 'info')

        extract_dir = os.path.join(temp_dir, 'extracted')
        if not extract_archive(archive_path, extract_dir, metadata['extract_type'], log_callback):
            if log_callback:
                log_callback(f"Failed to extract {tool_name}", 'error')
            return False

        # AIK is a directory-based tool. Preserve its complete archive tree;
        # copying only expected_files drops android_win_tools and its helpers.
        if tool_name in ('android_image_kitchen', 'unpackimg'):
            aik_source = None
            for root, _, files in os.walk(extract_dir):
                if 'unpackimg.bat' in files:
                    aik_source = root
                    break
            if aik_source is None:
                aik_source = extract_dir
            aik_dir = os.path.join(TOOLS_DIR, metadata['subdir'])
            ensure_dir(aik_dir)
            for entry in os.listdir(aik_source):
                source = os.path.join(aik_source, entry)
                destination = os.path.join(aik_dir, entry)
                if os.path.isdir(source):
                    shutil.copytree(source, destination, dirs_exist_ok=True)
                else:
                    shutil.copy2(source, destination)
            if log_callback:
                log_callback(f"Installed complete AIK tree to {aik_dir}", 'info')

        tool_dir = os.path.join(TOOLS_DIR, metadata['subdir'])
        ensure_dir(tool_dir)

        if not move_files_to_subdir(extract_dir, metadata['subdir'], metadata['expected_files'], log_callback):
            if log_callback:
                log_callback(f"Failed to organize {tool_name} files", 'error')
            return False

        if log_callback:
            log_callback(f"[Ok] {tool_name} setup complete", 'success')
        return True

    except Exception as e:
        if log_callback:
            log_callback(f"Setup failed for {tool_name}: {e}", 'error')
        return False
    finally:
        cleanup_temp_files(temp_dir)

def check_tool_updates(tool_name: str) -> Optional[str]:
    """Check if a tool has updates available (simplified version)"""
    # This would normally check version files or APIs
    # For now, return None (no update needed)
    return None

def update_tool_if_needed(tool_name: str, progress_callback=None, log_callback=None) -> bool:
    """Check and update a tool if needed"""
    new_version = check_tool_updates(tool_name)
    if new_version:
        if log_callback:
            log_callback(f"Updating {tool_name} to {new_version}...", 'info')
        return download_and_setup_tool(tool_name, progress_callback, log_callback)
    return True  # No update needed, consider success

def compute_md5(path: str, block_size: int = 1024*1024, length: Optional[int] = None) -> str:
    h = hashlib.md5()
    with open(path, "rb") as f:
        if length is None:
            length = os.path.getsize(path)
        remaining = length
        while remaining > 0:
            chunk_size = min(block_size, remaining)
            chunk = f.read(chunk_size)
            if not chunk:
                break
            h.update(chunk)
            remaining -= len(chunk)
        if remaining > 0:
            raise IOError(f"File read incomplete: expected {length} bytes, got {length - remaining} bytes")
    return h.hexdigest().lower()

def read_bytes(path: str, offset: int = 0, length: Optional[int] = None) -> bytes:
    with open(path, "rb") as f:
        f.seek(offset)
        return f.read() if length is None else f.read(length)

def is_admin() -> bool:
    """Check if the current process is running with administrator privileges."""
    try:
        return ctypes.windll.shell32.IsUserAnAdmin()
    except OSError:
        return False

def check_and_elevate():
    """Check admin status and elevate if needed, return True if we should continue."""
    if is_admin():
        print("Running with administrator privileges.")
        return True

    try:
        script = os.path.abspath(sys.argv[0])

        # Simple console prompt for admin elevation
        print("This application requires administrator privileges.")
        response = input("Restart with administrator privileges? (y/n): ").lower().strip()

        if response == 'y':
            result_code = ctypes.windll.shell32.ShellExecuteW(None, "runas", sys.executable, f'"{script}"', None, 1)
            if result_code > 32:
                print("Restarting with administrator privileges...")
                sys.exit(0)  # Exit current process, new admin process will continue
            else:
                print("Failed to restart with administrator privileges.")
                return False
        else:
            print("Continuing without administrator privileges.")
            print("Warning: Device detection and flashing features may not work properly.")
            return True
    except Exception as e:
        print(f"Failed to check admin privileges: {e}")
        return False

def run_as_admin():
    """Restart the application with administrator privileges."""
    try:
        if sys.platform.startswith('win'):
            # Get the current script path
            script = os.path.abspath(sys.argv[0])
            # Use ShellExecute to run as admin
            result = ctypes.windll.shell32.ShellExecuteW(None, "runas", sys.executable, f'"{script}"', None, 1)
            if result <= 32:  # Values <= 32 indicate failure
                return False
            sys.exit(0)  # Exit the current non-admin process
        else:
            # For non-Windows, assume it's already running with sufficient privileges
            return True
    except Exception as e:
        return False

# -------------------------
# TAR Operations
# -------------------------
def parse_tar_header(block: bytes) -> Optional[Dict[str, Any]]:
    """Parse 512-byte tar header"""
    if len(block) != TAR_BLOCK_SIZE or set(block) == {0}:
        return None
    
    try:
        name = block[0:100].rstrip(b'\x00').decode(errors='ignore')
        size_oct = block[124:136].rstrip(b'\x00').strip()
        size = int(size_oct or b'0', 8) if size_oct else 0
        typeflag = chr(block[156]) if block[156] else '0'
        prefix = block[345:500].rstrip(b'\x00').decode(errors='ignore')
        full_name = (prefix + "/" + name) if prefix else name
        
        return {
            'name': full_name,
            'size': size,
            'typeflag': typeflag,
            'raw_block': block
        }
    except Exception:
        return None

def list_tar_entries(tar_path: str) -> List[Tuple[str, int, int, int]]:
    """List TAR entries"""
    entries: List[Tuple[str, int, int, int]] = []
    with open(tar_path, "rb") as f:
        offset = 0
        while True:
            block = f.read(TAR_BLOCK_SIZE)
            if not block or len(block) < TAR_BLOCK_SIZE:
                break
            
            hdr = parse_tar_header(block)
            if not hdr:
                break
            
            entries.append((
                hdr['name'],
                offset,
                offset + TAR_BLOCK_SIZE,
                hdr['size']
            ))
            
            data_blocks = (hdr['size'] + TAR_BLOCK_SIZE - 1) // TAR_BLOCK_SIZE
            f.seek(data_blocks * TAR_BLOCK_SIZE, os.SEEK_CUR)
            offset = f.tell()
    
    return entries

def find_tar_entry(tar_path: str, target: str) -> Optional[Tuple[int, int, int]]:
    """Find entry and return offsets"""
    candidates = [target]
    if not target.startswith("./"):
        candidates.append("./" + target)
    else:
        candidates.append(target[2:])
    
    entries = list_tar_entries(tar_path)
    for name, hdr_off, data_off, size in entries:
        if name in candidates:
            return (hdr_off, data_off, size)
    return None

def replace_tar_entry_inplace(tar_path: str, entry_name: str, data: bytes,
                               pad_zeros: bool = True) -> None:
    """Replace TAR entry in-place and update MD5 if .tar.md5"""
    found = find_tar_entry(tar_path, entry_name)
    if not found:
        raise FileNotFoundError(f"Entry '{entry_name}' not found")

    hdr_off, data_off, orig_size = found

    if len(data) == orig_size:
        with open(tar_path, "r+b") as f:
            f.seek(data_off)
            f.write(data)
    elif len(data) < orig_size:
        if pad_zeros:
            data = data + b'\x00' * (orig_size - len(data))
            with open(tar_path, "r+b") as f:
                f.seek(data_off)
                f.write(data)
        else:
            raise ValueError("Replacement smaller and pad_zeros=False")
    else:
        raise ValueError(
            f"Replacement size ({len(data)}) > original ({orig_size}). "
            "In-place replacement not supported for growing entries."
        )

    if tar_path.lower().endswith('.tar.md5'):
        full_size = os.path.getsize(tar_path)
        tar_length = full_size - 32
        if tar_length > 0 and full_size % 32 == 0:
            new_md5 = compute_md5(tar_path, length=tar_length)
            with open(tar_path, "r+b") as f:
                f.seek(tar_length)
                f.write(new_md5.encode('ascii'))

def extract_tar_entry(tar_path: str, entry_name: str, out_path: str) -> None:
    """Extract single TAR entry"""
    found = find_tar_entry(tar_path, entry_name)
    if not found:
        raise FileNotFoundError(f"Entry '{entry_name}' not found")
    
    _, data_off, size = found
    data = read_bytes(tar_path, data_off, size)
    with open(out_path, "wb") as f:
        f.write(data)

# -------------------------
# MD5 Footer Operations
# -------------------------
def strip_md5_footer(md5_path: str, tar_path: str) -> str:
    """
    Strip MD5 footer from a .tar.md5 file.
    Samsung .tar.md5 files have MD5 hash appended at the end.
    The format can be: 32 hex chars, or "hash  filename\n" format.
    """
    with open(md5_path, 'rb') as f:
        f.seek(0, 2)
        file_size = f.tell()
        
        # First try: check if last 32 bytes are pure hex
        if file_size >= 32:
            f.seek(-32, 2)
            footer = f.read(32)
            
            if all(c in b"0123456789abcdefABCDEF" for c in footer):
                # Pure 32-byte hex footer
                md5_hex_str = footer.decode('ascii')
                footer_start = file_size - 32

                # Write the tar data (everything before the MD5 footer)
                f.seek(0)
                with open(tar_path, 'wb') as tar_file:
                    remaining = footer_start
                    chunk_size = 1024 * 1024
                    while remaining > 0:
                        to_read = min(chunk_size, remaining)
                        tar_file.write(f.read(to_read))
                        remaining -= to_read

                return md5_hex_str
        
        # Second try: find MD5 hash in larger footer (up to 512 bytes)
        search_size = min(512, file_size)
        f.seek(-search_size, 2)
        tail = f.read(search_size)
        
        # Look for 32 consecutive hex characters (MD5 hash)
        import re
        # Pattern: 32 hex chars possibly followed by spaces and filename
        matches = list(re.finditer(rb'([0-9a-fA-F]{32})', tail))
        
        if not matches:
            raise ValueError("No MD5 hash found in file footer")
        
        # Use the last match (most likely to be the actual hash)
        last_match = matches[-1]
        md5_hex_str = last_match.group(1).decode('ascii')
        
        # Calculate where the TAR data ends (before the MD5 footer)
        # The footer starts where we found the hash
        footer_start = file_size - search_size + last_match.start()
        
        # Write the tar data (everything before the MD5 footer)
        f.seek(0)
        with open(tar_path, 'wb') as tar_file:
            remaining = footer_start
            chunk_size = 1024 * 1024
            while remaining > 0:
                to_read = min(chunk_size, remaining)
                tar_file.write(f.read(to_read))
                remaining -= to_read

    return md5_hex_str

def append_md5_footer(tar_path: str, out_md5: str) -> str:
    """Compute MD5 and append in Samsung Odin format.

    Samsung .tar.md5 format is: TAR data + 32-byte MD5 hash.
    Some variants may have padding before the MD5, but the simple
    append of 32 bytes works with most Odin versions.
    """
    md5_hash = compute_md5(tar_path)

    with open(tar_path, "rb") as src, open(out_md5, "wb") as dst:
        shutil.copyfileobj(src, dst)
        dst.write(md5_hash.encode('ascii'))

    return md5_hash

def verify_tar_md5(md5_file: str) -> Tuple[bool, str]:
    """Verify MD5"""
    tmp = tempfile.mktemp(suffix=".tar")
    try:
        try:
            footer = strip_md5_footer(md5_file, tmp)
        except ValueError as e:
            return False, str(e)
        computed = compute_md5(tmp)
        return (computed == footer.lower(), computed)
    finally:
        try:
            os.remove(tmp)
        except Exception:
            pass

# -------------------------
# ROM Building Operations
# -------------------------
def extract_system_image(system_img: str, out_dir: str) -> None:
    """Extract system.img using simg2img and mount"""
    ensure_dir(out_dir)

    raw_img = None
    try:
        magic = read_bytes(system_img, 0, 4)
        if magic == b'\x3a\xff\x26\xed':  # Sparse image magic
            raw_img = tempfile.mktemp(suffix=".img")
            simg2img = tool_resolve("simg2img")
            if simg2img:
                result = run_cmd([simg2img, system_img, raw_img])
                if result.returncode == 0:
                    system_img = raw_img
                else:
                    raw_img = None
            else:
                raise FileNotFoundError("simg2img not found")

        seven_z = tool_resolve("7z")
        if seven_z:
            result = run_cmd([seven_z, "x", system_img, f"-o{out_dir}"])
            if result.returncode == 0:
                return

        bsdtar = tool_resolve("bsdtar")
        if bsdtar:
            result = run_cmd([bsdtar, "-xf", system_img, "-C", out_dir])
            if result.returncode == 0:
                return

        raise RuntimeError("Could not extract system image")
    finally:
        if raw_img and os.path.exists(raw_img):
            try:
                os.remove(raw_img)
            except OSError:
                pass

def build_rom_from_images(images_dir: str, out_zip: str,
                         rom_name: str = "CustomROM") -> None:
    """Build ROM ZIP from extracted images"""
    ensure_dir(os.path.dirname(out_zip))
    
    seven_z = tool_resolve("7z")
    if not seven_z:
        raise FileNotFoundError("Compression tool not found")
    
    # Create ROM structure
    rom_dir = tempfile.mkdtemp(prefix="rom_build_")
    
    # Copy build system files
    for item in os.listdir(images_dir):
        src = os.path.join(images_dir, item)
        if os.path.isdir(src):
            shutil.copytree(src, os.path.join(rom_dir, item))
        else:
            shutil.copy2(src, rom_dir)
    
    # Create META-INF if needed
    meta_dir = os.path.join(rom_dir, "META-INF", "com", "google", "android")
    ensure_dir(meta_dir)
    
    # Add placeholder updater-script (needs device-specific customization)
    with open(os.path.join(meta_dir, "updater-script"), "w") as f:
        f.write('ui_print("Installing Custom ROM...");\n')
        f.write('package_extract_dir("system", "/system");\n')
        f.write('ui_print("Installation complete");\n')
    
    # Compress with files at root
    result = run_cmd([seven_z, "a", "-tzip", out_zip, "."], cwd=rom_dir)
    
    shutil.rmtree(rom_dir, ignore_errors=True)
    
    if result.returncode != 0:
        raise RuntimeError("ROM build failed")

def modify_system_props(system_dir: str, properties: Dict[str, str]) -> None:
    """Modify system properties"""
    build_prop = os.path.join(system_dir, "build.prop")
    if not os.path.exists(build_prop):
        return
    
    with open(build_prop, "r") as f:
        lines = f.readlines()
    
    # Update existing or add new properties
    prop_dict = {}
    for line in lines:
        if "=" in line:
            key, val = line.split("=", 1)
            prop_dict[key.strip()] = val.strip()
    
    prop_dict.update(properties)
    
    with open(build_prop, "w") as f:
        for key, val in prop_dict.items():
            f.write(f"{key}={val}\n")

def create_keystore(keystore_path: str, key_alias: str, key_pass: str, store_pass: str,
                   dname: str = "CN=Android Debug,O=Android,C=US") -> None:
    """Create a new keystore with keytool"""
    keytool = tool_resolve("keytool")
    if not keytool:
        raise FileNotFoundError("keytool not found. Ensure Java JDK is installed.")

    cmd = [
        keytool, "-genkeypair",
        "-v",
        "-keystore", keystore_path,
        "-alias", key_alias,
        "-keyalg", "RSA",
        "-keysize", "2048",
        "-validity", "10000",
        "-storepass", store_pass,
        "-keypass", key_pass,
        "-dname", dname
    ]

    result = run_cmd(cmd)
    if result.returncode != 0:
        raise RuntimeError(f"Keystore creation failed: {result.stderr.decode(errors='ignore')}")

def sign_apk_with_debug(apk_path: str) -> None:
    """Sign APK with Android debug keystore"""
    # Zipalign first
    zipalign = tool_resolve("zipalign")
    if zipalign:
        aligned = apk_path + ".aligned"
        result = run_cmd([zipalign, "-f", "4", apk_path, aligned])
        if result.returncode == 0:
            shutil.move(aligned, apk_path)
    else:
        raise FileNotFoundError("zipalign not found. Cannot align APK before signing.")

    apksigner_path = tool_resolve_apksigner()
    if not apksigner_path:
        # Fallback: try to use jarsigner from JDK if apksigner is not available
        jarsigner = tool_resolve("jarsigner")
        if jarsigner:
            return sign_apk_with_jarsigner(apk_path)
        raise FileNotFoundError("Neither apksigner.jar nor jarsigner found. Please ensure apksigner.jar is in the tools directory or install a JDK.")

    java_path = tool_resolve("java")
    if not java_path:
        raise FileNotFoundError("Java runtime not found to execute apksigner.jar. Ensure Java is installed and in PATH, or 'java.exe' is in the 'tools/' directory.")

    # Use Android's default debug keystore
    debug_keystore = os.path.join(os.path.expanduser("~"), ".android", "debug.keystore")
    if not os.path.exists(debug_keystore):
        # Create debug keystore if it doesn't exist
        ensure_dir(os.path.dirname(debug_keystore))
        create_keystore(debug_keystore, "androiddebugkey", "android", "android",
                       "CN=Android Debug,O=Android,C=US")

    # apksigner command with debug keystore
    cmd = [
        java_path, "-jar", apksigner_path, "sign",
        "--ks", debug_keystore,
        "--ks-key-alias", "androiddebugkey",
        "--ks-pass", "pass:android",
        apk_path
    ]

    result = run_cmd(cmd)
    if result.returncode != 0:
        raise RuntimeError(f"APK signing failed: {result.stderr.decode(errors='ignore')}")

def sign_apk_with_jarsigner(apk_path: str) -> None:
    """Fallback signing using jarsigner from JDK"""
    jarsigner = tool_resolve("jarsigner")
    if not jarsigner:
        raise FileNotFoundError("jarsigner not found. Please install a JDK.")

    # Create a temporary debug keystore for jarsigner
    debug_keystore = os.path.join(tempfile.gettempdir(), "debug.keystore")
    try:
        # Create debug keystore
        create_keystore(debug_keystore, "androiddebugkey", "android", "android",
                       "CN=Android Debug,O=Android,C=US")

        # jarsigner command
        cmd = [
            jarsigner, "-verbose", "-sigalg", "SHA1withRSA", "-digestalg", "SHA1",
            "-keystore", debug_keystore,
            "-storepass", "android",
            "-keypass", "android",
            apk_path, "androiddebugkey"
        ]

        result = run_cmd(cmd)
        if result.returncode != 0:
            raise RuntimeError(f"APK signing with jarsigner failed: {result.stderr.decode(errors='ignore')}")

    finally:
        # Clean up temporary keystore
        try:
            os.remove(debug_keystore)
        except OSError:
            pass

def sign_apk(apk_path: str, keystore: str, key_alias: str, key_pass: str) -> None:
    """Sign APK"""
    # Zipalign first
    zipalign = tool_resolve("zipalign")
    if zipalign:
        aligned = apk_path + ".aligned"
        result = run_cmd([zipalign, "-f", "4", apk_path, aligned])
        if result.returncode == 0:
            shutil.move(aligned, apk_path)
    else:
        raise FileNotFoundError("zipalign not found. Cannot align APK before signing.")

    apksigner_path = tool_resolve_apksigner()
    if not apksigner_path:
        raise FileNotFoundError("apksigner.jar not found. Ensure it's in 'tools/boot_editor/aosp/apksigner/'.")

    java_path = tool_resolve("java")
    if not java_path:
        raise FileNotFoundError("Java runtime not found to execute apksigner.jar. Ensure Java is installed and in PATH, or 'java.exe' is in the 'tools/' directory.")

    if not keystore:
        raise ValueError("Keystore path is required for signing.")

    # apksigner command
    cmd = [
        java_path, "-jar", apksigner_path, "sign",
        "--ks", keystore,
        "--ks-key-alias", key_alias,
        "--ks-pass", f"pass:{key_pass}",
        apk_path
    ]

    result = run_cmd(cmd)
    if result.returncode != 0:
        raise RuntimeError(f"APK signing failed: {result.stderr.decode(errors='ignore')}")

def get_apktool_cmd(action: str, args: List[str]) -> List[str]:
    """Get command for apktool, handling wrapper or jar"""
    apktool_path = tool_resolve("apktool")
    if apktool_path:
        if apktool_path.lower().endswith('.jar'):
            java_path = tool_resolve("java")
            if not java_path:
                raise FileNotFoundError("Java runtime not found to execute apktool.jar. Ensure Java is installed and in PATH, or 'java.exe' is in the 'tools/' directory.")
            if not os.access(java_path, os.X_OK):
                raise PermissionError(f"Java executable '{java_path}' is not executable. Check file permissions.")
            return [java_path, "-jar", apktool_path, action] + args
        else: # Assume it's an executable like .exe or .bat
            if not os.access(apktool_path, os.X_OK):
                raise PermissionError(f"Apktool executable '{apktool_path}' is not executable. Check file permissions.")
            return [apktool_path, action] + args
    
    raise FileNotFoundError("apktool not found (neither apktool.exe nor apktool.jar with java). Ensure 'apktool.exe' or 'apktool.jar' is in the 'tools/' directory or in system PATH.")

def decompile_apk(apk_path: str, out_dir: str) -> None:
    """Decompile APK"""
    ensure_dir(out_dir) # Ensure output directory exists
    cmd = get_apktool_cmd("d", [apk_path, "-o", out_dir, "-f"])
    result = run_cmd(cmd)
    if result.returncode != 0:
        raise RuntimeError(f"APK decompile failed: {result.stderr.decode(errors='ignore')}")

def recompile_apk(src_dir: str, out_apk: str, target_sdk: Optional[int] = None) -> None:
    """Recompile APK with proper compression settings for Android R+"""
    cmd = get_apktool_cmd("b", [src_dir, "-o", out_apk])

    # Use apktool with specific flags to ensure proper resource handling
    apktool_path = tool_resolve("apktool")
    if apktool_path and apktool_path.lower().endswith('.jar'):
        # For apktool.jar, use flags that help with Android R+ compatibility
        java_path = tool_resolve("java")
        if java_path:
            cmd = [java_path, "-jar", apktool_path, "b", src_dir, "-o", out_apk, "--use-aapt2"]
    else:
        # For executable apktool, use basic command
        cmd = get_apktool_cmd("b", [src_dir, "-o", out_apk])

    result = run_cmd(cmd)
    if result.returncode != 0:
        raise RuntimeError(f"APK recompile failed: {result.stderr.decode(errors='ignore')}")

    # Post-process the APK to ensure resources.arsc is uncompressed and aligned
    fix_apk_compression(out_apk)

def unpack_boot_img(boot_img: str, out_dir: str) -> Dict[str, Any]:
    """Unpack a boot/recovery image. Returns a dict with the method used and the
    output paths. After unpacking, the ramdisk is automatically extracted to
    `<out_dir>/ramdisk/` if AIK is used."""
    ensure_dir(out_dir)
    errors = []

    # 1) magiskboot (fast, produces kernel + ramdisk.cpio directly)
    magiskboot = tool_resolve("magiskboot")
    if magiskboot:
        boot_basename = os.path.basename(boot_img)
        dest_path = os.path.join(out_dir, boot_basename)
        if os.path.normpath(os.path.abspath(boot_img)) != os.path.normpath(os.path.abspath(dest_path)):
            shutil.copy2(boot_img, dest_path)
        result = run_cmd([magiskboot, "unpack", boot_basename], cwd=out_dir)
        if result.returncode == 0:
            return {'method': 'magiskboot', 'status': 'success', 'out_dir': out_dir}

    # 2) AIK unpackimg.bat (handles AOSP, AOSP_VNDR, AOSP-PXA, ELF, KRNL, OSIP,
    #    U-Boot, BLOB, CHROMEOS, DHTB, NOOK, Sony SIN; supports gzip/lzop/lzma/
    #    xz/bzip2/lz4/lz4-l/cpio ramdisk; auto-unpacks ramdisk to split_img/ and
    #    ramdisk/ subdirectories)
    aik = tool_resolve("unpackimg")
    if aik:
        aik_root = os.path.dirname(aik)
        # AIK uses %bin% (= aik_root/android_win_tools) and writes split_img/
        # and ramdisk/ as subdirectories of CWD
        result = run_cmd([aik, boot_img], cwd=out_dir)
        if result.returncode == 0:
            # Find the produced split_img/ and ramdisk/ directories and merge them
            split_img = os.path.join(out_dir, "split_img")
            ramdisk = os.path.join(out_dir, "ramdisk")
            return {
                'method': 'AIK',
                'status': 'success',
                'out_dir': out_dir,
                'split_img': split_img if os.path.isdir(split_img) else None,
                'ramdisk': ramdisk if os.path.isdir(ramdisk) else None,
            }
        err = result.stderr.decode(errors='replace') if result and result.stderr else ''
        errors.append(f"AIK: {err.strip()[:200]}")

    # 3) 7z (works for some images, no ramdisk handling)
    seven_z = tool_resolve("7z")
    if seven_z:
        result = run_cmd([seven_z, "x", boot_img, f"-o{out_dir}"])
        if result.returncode == 0:
            return {'method': '7z', 'status': 'success', 'out_dir': out_dir}
        errors.append(f"7z: {result.stderr.decode(errors='replace')[:200] if result and result.stderr else ''}")

    # 4) bsdtar
    bsdtar = tool_resolve("bsdtar")
    if bsdtar:
        result = run_cmd([bsdtar, "-xf", boot_img, "-C", out_dir])
        if result.returncode == 0:
            return {'method': 'bsdtar', 'status': 'success', 'out_dir': out_dir}

    raise RuntimeError(
        "Boot image unpacker not found or all unpackers failed. "
        "Install magiskboot or AIK (with android_win_tools). Errors: " + " | ".join(errors)
    )

def repack_boot_img(work_dir: str, out_img: str, prefer: str = "auto") -> None:
    """Repack a boot image. prefers magiskboot, falls back to AIK.
    `work_dir` should be the directory produced by unpack_boot_img."""
    if prefer in ("auto", "magiskboot"):
        magiskboot = tool_resolve("magiskboot")
        if magiskboot:
            result = run_cmd([magiskboot, "repack", "boot.img"], cwd=work_dir)
            if result.returncode == 0 and os.path.exists(os.path.join(work_dir, "new-boot.img")):
                shutil.copy(os.path.join(work_dir, "new-boot.img"), out_img)
                return

    if prefer in ("auto", "aik"):
        aik = tool_resolve("repackimg")
        if aik:
            result = run_cmd([aik], cwd=work_dir)
            if result.returncode == 0:
                # AIK writes image-new.img (or unsigned-new.img if signed)
                for name in ("image-new.img", "unsigned-new.img"):
                    src = os.path.join(work_dir, name)
                    if os.path.exists(src):
                        shutil.copy(src, out_img)
                        return

    raise RuntimeError("Boot repack failed: no working repacker found")

def extract_kernel(boot_unpack_dir: str, out_path: str) -> None:
    """Extract kernel from unpacked boot directory"""
    kernel_path = os.path.join(boot_unpack_dir, "kernel")
    if not os.path.exists(kernel_path):
        raise FileNotFoundError("kernel not found in unpacked directory. Make sure you have unpacked a boot image first.")
    shutil.copy(kernel_path, out_path)

def extract_dtb(boot_unpack_dir: str, out_path: str) -> None:
    """Extract dtb from unpacked boot directory"""
    dtb_path = os.path.join(boot_unpack_dir, "dtb")
    if not os.path.exists(dtb_path):
        raise FileNotFoundError("dtb not found in unpacked directory. Make sure you have unpacked a boot image first.")
    shutil.copy(dtb_path, out_path)

def extract_ramdisk(cpio_file: str, out_dir: str) -> None:
    """Extract ramdisk (CPIO archive, possibly gz/lz4/lzma/xz/bzip2/lzop compressed).
    Detects compression by magic bytes, then uses the right tool to decompress,
    then uses cpio (or AIK) to extract."""
    ensure_dir(out_dir)

    if not os.path.exists(cpio_file):
        raise FileNotFoundError(f"Ramdisk not found: {cpio_file}")

    # Detect compression by magic bytes
    with open(cpio_file, 'rb') as f:
        magic = f.read(8)

    work_file = cpio_file
    tmp_files = []

    try:
        # LZ4 legacy frame magic: 02 21 4C 18
        if magic[:4] == b'\x02\x21\x4c\x18':
            lz4 = tool_resolve("lz4")
            if not lz4:
                raise FileNotFoundError("lz4 not found, cannot decompress lz4 ramdisk")
            tmp = tempfile.mktemp(suffix=".cpio")
            tmp_files.append(tmp)
            result = run_cmd([lz4, "-d", "-f", cpio_file, tmp])
            if result.returncode != 0:
                raise RuntimeError(f"LZ4 decompress failed: {result.stderr.decode(errors='replace')[:200]}")
            work_file = tmp

        # LZ4 frame format (newer): 04 22 4D 18
        elif magic[:4] == b'\x04\x22\x4d\x18':
            lz4 = tool_resolve("lz4")
            if not lz4:
                raise FileNotFoundError("lz4 not found")
            tmp = tempfile.mktemp(suffix=".cpio")
            tmp_files.append(tmp)
            result = run_cmd([lz4, "-d", "-f", "--frame-format", cpio_file, tmp])
            if result.returncode != 0:
                # Try without --frame-format (older lz4 doesn't support it)
                result = run_cmd([lz4, "-d", "-f", cpio_file, tmp])
                if result.returncode != 0:
                    raise RuntimeError(f"LZ4 frame decompress failed: {result.stderr.decode(errors='replace')[:200]}")
            work_file = tmp

        # gzip magic: 1F 8B
        elif magic[:2] == b'\x1f\x8b':
            gzip = tool_resolve("gzip")
            if not gzip:
                raise FileNotFoundError("gzip not found")
            tmp = tempfile.mktemp(suffix=".cpio")
            tmp_files.append(tmp)
            with open(cpio_file, 'rb') as f_in, open(tmp, 'wb') as f_out:
                result = run_cmd([gzip, "-dc"], input_data=f_in.read())
                if result.returncode != 0:
                    raise RuntimeError("gzip decompress failed")
                f_out.write(result.stdout if isinstance(result.stdout, bytes) else b"")
            work_file = tmp

        # xz magic: FD 37 7A 58 5A 00
        elif magic[:6] == b'\xfd7zXZ\x00':
            xz = tool_resolve("xz")
            if not xz:
                raise FileNotFoundError("xz not found")
            tmp = tempfile.mktemp(suffix=".cpio")
            tmp_files.append(tmp)
            result = run_cmd([xz, "-dc", cpio_file])
            if result.returncode != 0:
                raise RuntimeError("xz decompress failed")
            with open(tmp, 'wb') as f_out:
                f_out.write(result.stdout if isinstance(result.stdout, bytes) else b"")
            work_file = tmp

        # lzma magic: 5D 00 00 (followed by size)
        elif magic[0] == 0x5d and magic[1] == 0x00 and magic[2] == 0x00:
            xz = tool_resolve("xz")
            if not xz:
                raise FileNotFoundError("xz not found (needed for lzma)")
            tmp = tempfile.mktemp(suffix=".cpio")
            tmp_files.append(tmp)
            result = run_cmd([xz, "-Flzma", "-dc", cpio_file])
            if result.returncode != 0:
                raise RuntimeError("lzma decompress failed")
            with open(tmp, 'wb') as f_out:
                f_out.write(result.stdout if isinstance(result.stdout, bytes) else b"")
            work_file = tmp

        # bzip2 magic: 42 5A 68 (BZh)
        elif magic[:3] == b'BZh':
            bz = tool_resolve("bzip2")
            if not bz:
                raise FileNotFoundError("bzip2 not found")
            tmp = tempfile.mktemp(suffix=".cpio")
            tmp_files.append(tmp)
            result = run_cmd([bz, "-dc", cpio_file])
            if result.returncode != 0:
                raise RuntimeError("bzip2 decompress failed")
            with open(tmp, 'wb') as f_out:
                f_out.write(result.stdout if isinstance(result.stdout, bytes) else b"")
            work_file = tmp

        # lzop magic: 89 4C 5A 4F
        elif magic[:4] == b'\x89LZO':
            lzop = tool_resolve("lzop")
            if not lzop:
                raise FileNotFoundError("lzop not found")
            tmp = tempfile.mktemp(suffix=".cpio")
            tmp_files.append(tmp)
            result = run_cmd([lzop, "-dc", cpio_file])
            if result.returncode != 0:
                raise RuntimeError("lzop decompress failed")
            with open(tmp, 'wb') as f_out:
                f_out.write(result.stdout if isinstance(result.stdout, bytes) else b"")
            work_file = tmp

        # Plain CPIO: "070701" (newc) or "070702" (newc with crc)
        with open(work_file, 'rb') as f:
            hdr = f.read(6)
        if hdr not in (b'070701', b'070702'):
            raise RuntimeError(
                f"Unknown ramdisk format. Magic: {hdr!r}. "
                "Expected CPIO (070701/070702), or compressed ramdisk (gzip/xz/lz4/lzma/bzip2/lzop)."
            )

        # Try bsdtar first
        bsdtar = tool_resolve("bsdtar")
        if bsdtar:
            result = run_cmd([bsdtar, "-xf", work_file, "-C", out_dir])
            if result.returncode == 0:
                return

        # Fall back to cpio
        cpio = tool_resolve("cpio")
        if cpio:
            with open(work_file, 'rb') as f:
                cpio_data = f.read()
            result = run_cmd([cpio, "-idm", "--no-absolute-filenames"], cwd=out_dir, input_data=cpio_data)
            if result.returncode == 0:
                return
            err = result.stderr.decode(errors='replace') if result and result.stderr else "unknown"
            raise RuntimeError(f"cpio extraction failed: {err[:300]}")

        # Last resort: try AIK's cpio via unpackimg's split_img + ramdisk workflow
        raise RuntimeError("No cpio or bsdtar available to extract ramdisk")
    finally:
        for tmp in tmp_files:
            try:
                if os.path.exists(tmp):
                    os.remove(tmp)
            except OSError:
                pass

def create_ramdisk(src_dir: str, out_cpio: str, compress: str = "gzip") -> None:
    """Create a ramdisk from a directory. `compress` controls the compression
    applied AFTER creating the cpio: 'gzip', 'lz4', 'lzma', 'xz', 'bzip2',
    'lzop', or 'none' for uncompressed cpio. Detects existing tools."""
    if not os.path.isdir(src_dir):
        raise FileNotFoundError(f"Source dir not found: {src_dir}")

    # First, try cpio (newc format, the standard for Android ramdisks)
    cpio = tool_resolve("cpio")
    bsdtar = tool_resolve("bsdtar")

    tmp_cpio = tempfile.mktemp(suffix=".cpio")
    cpio_created = False

    try:
        if bsdtar:
            # bsdtar with --format newc creates a newc-format cpio
            result = run_cmd([bsdtar, "--format", "newc", "-cf", tmp_cpio, "-C", src_dir, "."])
            if result.returncode == 0:
                cpio_created = True

        if not cpio_created and cpio:
            # Use cpio -o with find pipe (correct way to create a cpio archive)
            result = run_cmd([cpio, "-o", "-H", "newc", "--quiet",
                              "-F", tmp_cpio], cwd=src_dir,
                             input_data=_find_files_for_cpio(src_dir).encode('utf-8'))
            if result.returncode == 0 and os.path.exists(tmp_cpio) and os.path.getsize(tmp_cpio) > 0:
                cpio_created = True

        if not cpio_created:
            raise FileNotFoundError("Neither bsdtar nor cpio could create a ramdisk")

        # Now compress (or copy as-is) to the final output path
        if compress == "none" or not compress:
            shutil.move(tmp_cpio, out_cpio)
            return

        compress_tool = {
            "gzip":  ("gzip",  ["-9f"]),
            "lz4":   ("lz4",   ["-9f", "-l"]),  # -l = legacy format (Android-friendly)
            "lzma":  ("xz",    ["-Flzma", "-9f"]),
            "xz":    ("xz",    ["-9f", "-Ccrc32"]),
            "bzip2": ("bzip2", ["-9f"]),
            "lzop":  ("lzop",  ["-9f"]),
        }.get(compress.lower() if compress else "gzip")

        if not compress_tool:
            shutil.move(tmp_cpio, out_cpio)
            return

        tool_name, args = compress_tool
        tool_path = tool_resolve(tool_name)
        if not tool_path:
            # Fall back to plain cpio
            shutil.move(tmp_cpio, out_cpio)
            return

        result = run_cmd([tool_path] + args, input_data=open(tmp_cpio, 'rb').read())
        if result.returncode == 0:
            out_bytes = result.stdout if isinstance(result.stdout, bytes) else b""
            with open(out_cpio, 'wb') as f:
                f.write(out_bytes)
        else:
            # Compressor failed; keep plain cpio
            shutil.move(tmp_cpio, out_cpio)
    finally:
        if os.path.exists(tmp_cpio):
            try:
                os.remove(tmp_cpio)
            except OSError:
                pass

def _find_files_for_cpio(src_dir: str) -> str:
    """Generate a list of files for cpio -o via stdin (relative paths, newline-separated)."""
    lines = []
    for root, dirs, files in os.walk(src_dir):
        rel = os.path.relpath(root, src_dir)
        if rel != ".":
            lines.append(rel)
        for f in files:
            full = os.path.join(root, f)
            rel_f = os.path.relpath(full, src_dir)
            lines.append(rel_f)
    return "\n".join(lines) + "\n"

# -------------------------
# LZ4 Operations
# -------------------------
def lz4_decompress(src: str, dst: str, force: bool = True) -> None:
    """Decompress LZ4"""
    lz4 = tool_resolve("lz4")
    if not lz4:
        raise FileNotFoundError("lz4 not found")
    
    cmd = [lz4, "-d"]
    if force:
        cmd.append("-f")
    cmd.extend([src, dst])
    
    result = run_cmd(cmd)
    if result.returncode != 0:
        raise RuntimeError(f"LZ4 decompress failed")

def lz4_compress(src: str, dst: str, level: int = 9, force: bool = True) -> None:
    """Compress LZ4"""
    lz4 = tool_resolve("lz4")
    if not lz4:
        raise FileNotFoundError("lz4 not found")
    
    cmd = [lz4]
    if force:
        cmd.append("-f")
    cmd.append(f"-{level}")
    cmd.extend([src, dst])
    
    result = run_cmd(cmd)
    if result.returncode != 0:
        raise RuntimeError(f"LZ4 compress failed")

# -------------------------
# Image Operations
# -------------------------
def sparse_to_raw(sparse_img: str, raw_img: str) -> None:
    """Convert sparse to raw"""
    simg2img = tool_resolve("simg2img")
    if not simg2img:
        raise FileNotFoundError("simg2img not found")
    
    result = run_cmd([simg2img, sparse_img, raw_img])
    if result.returncode != 0:
        raise RuntimeError("simg2img failed")

def raw_to_sparse(raw_img: str, sparse_img: str, block_size: int = 4096) -> None:
    """Convert raw to sparse"""
    img2simg = tool_resolve("img2simg")
    if not img2simg:
        raise FileNotFoundError("img2simg not found")

    result = run_cmd([img2simg, raw_img, sparse_img, str(block_size)])
    if result.returncode != 0:
        raise RuntimeError("img2simg failed")

def fix_apk_compression(apk_path: str) -> None:
    """Fix APK compression to ensure resources.arsc is uncompressed and aligned for Android R+"""
    temp_dir = tempfile.mkdtemp(prefix="apk_fix_")

    try:
        seven_z = tool_resolve("7z")
        if not seven_z:
            return  # Cannot fix without 7z

        # Extract APK contents
        result = run_cmd([seven_z, "x", apk_path, f"-o{temp_dir}"])
        if result.returncode != 0:
            return  # Skip if extraction fails

        # Check if resources.arsc exists
        resources_arsc = os.path.join(temp_dir, "resources.arsc")
        if not os.path.exists(resources_arsc):
            return  # No resources.arsc to fix

        # Remove original APK
        os.remove(apk_path)

        # Create exclusion list for resources.arsc (store uncompressed)
        exclude_file = os.path.join(temp_dir, "exclude.txt")
        with open(exclude_file, 'w') as f:
            f.write("resources.arsc\n")

        # First, add resources.arsc uncompressed
        result = run_cmd([
            seven_z, "a", "-tzip", "-mx=0", "-r", apk_path, "resources.arsc"
        ], cwd=temp_dir)

        if result.returncode == 0:
            # Then add everything else with compression, excluding resources.arsc
            result = run_cmd([
                seven_z, "a", "-tzip", "-mx=9", "-r", "-x@exclude.txt", apk_path, "."
            ], cwd=temp_dir)

        # Apply zipalign for proper alignment if available
        zipalign = tool_resolve("zipalign")
        if zipalign and os.path.exists(apk_path):
            aligned_apk = apk_path + ".aligned"
            result = run_cmd([zipalign, "-f", "4", apk_path, aligned_apk])
            if result.returncode == 0:
                import shutil
                shutil.move(aligned_apk, apk_path)
            else:
                try:
                    os.remove(aligned_apk)
                except OSError:
                    pass

    finally:
        # Cleanup
        import shutil
        shutil.rmtree(temp_dir, ignore_errors=True)

# -------------------------
# Heimdall Flashing
# -------------------------
def heimdall_detect_device() -> Tuple[bool, str]:
    """Detect device and return (success, device_info)"""
    heimdall = tool_resolve("heimdall")
    if not heimdall:
        return False, "Heimdall not found"

    result = run_cmd([heimdall, "detect"])
    if result.returncode == 0:
        output = result.stdout.decode(errors='replace').strip()
        return True, output if output else "Device detected"
    else:
        error = result.stderr.decode(errors='replace').strip()
        return False, error if error else "No device detected"

def heimdall_flash(partition_map: Dict[str, str]) -> bool:
    """Flash via Heimdall"""
    heimdall = tool_resolve("heimdall")
    if not heimdall:
        raise FileNotFoundError("heimdall not found")
    
    cmd = [heimdall, "flash"]
    for partition, img_path in partition_map.items():
        cmd.extend([f"--{partition}", img_path])
    
    result = run_cmd(cmd, capture=False)
    return result.returncode == 0

# -------------------------
# GUI: Log Console
# -------------------------
class LogConsole(ttk.Frame):
    """Logging console"""
    def __init__(self, parent, **kwargs):
        super().__init__(parent, **kwargs)
        self._build_ui()
    
    def _build_ui(self):
        toolbar = ttk.Frame(self)
        toolbar.pack(fill='x', padx=5, pady=2)
        
        ttk.Button(toolbar, text="Clear", command=self.clear).pack(side='left', padx=2)
        ttk.Button(toolbar, text="Save Log", command=self.save_log).pack(side='left', padx=2)
        
        self.text = tk.Text(self, wrap='word', height=12,
                           bg=COLORS['log_bg'], fg=COLORS['log_fg'],
                           font=('Consolas', 9))
        self.text.pack(fill='both', expand=True, padx=5, pady=5)
        
        self.text.tag_config('error', foreground=COLORS['error'])
        self.text.tag_config('warning', foreground=COLORS['warning'])
        self.text.tag_config('success', foreground=COLORS['success'])
        self.text.tag_config('info', foreground=COLORS['log_fg'])
        
        vsb = ttk.Scrollbar(self.text, orient='vertical', command=self.text.yview)
        vsb.pack(side='right', fill='y')
        self.text.config(yscrollcommand=vsb.set)
    
    def log(self, msg: str, level: str = 'info'):
        timestamp = datetime.now().strftime('%H:%M:%S')
        full_msg = f"[{timestamp}] {msg}\n"
        self.text.insert(tk.END, full_msg, level)
        self.text.see(tk.END)
    
    def clear(self):
        self.text.delete('1.0', tk.END)
    
    def save_log(self):
        path = filedialog.asksaveasfilename(defaultextension=".log",
                                           filetypes=[("Log files", "*.log")])
        if path:
            with open(path, 'w') as f:
                f.write(self.text.get('1.0', tk.END))

# -------------------------
# GUI: Text Output Dialog
# -------------------------
class TextOutputDialog(tk.Toplevel):
    """A simple dialog to display text output."""
    def __init__(self, parent, title: str, text_content: str):
        super().__init__(parent)
        self.title(title)
        self.resizable(True, True)
        self.configure(bg=COLORS['bg_card'])

        self.text_area = scrolledtext.ScrolledText(self, wrap='word', font=('Consolas', 10),
                                                  bg=COLORS['log_bg'], fg=COLORS['log_fg'])
        self.text_area.insert(tk.END, text_content)
        self.text_area.config(state='disabled')
        self.text_area.pack(fill=tk.BOTH, expand=True, padx=10, pady=10)

        close_button = ttk.Button(self, text="Close", command=self.destroy)
        close_button.pack(pady=5)

        self.transient(parent)
        self.grab_set()
        
        # Center the dialog
        self.update_idletasks()
        width = 600
        height = 400
        x = (self.winfo_screenwidth() // 2) - (width // 2)
        y = (self.winfo_screenheight() // 2) - (height // 2)
        self.geometry(f"{width}x{height}+{x}+{y}")

# Helper used by the hex editor's word analysis dialog.
def _int_to_float(val: int, size: int) -> str:
    """Convert an int to its IEEE 754 float representation."""
    import struct
    if size == 4:
        return str(struct.unpack("<f", struct.pack("<I", val & 0xFFFFFFFF))[0])
    if size == 8:
        return str(struct.unpack("<d", struct.pack("<Q", val & 0xFFFFFFFFFFFFFFFF))[0])
    return "n/a"

