                   'actual', 'abstract', 'annotation', 'companion', 'const', 'crossinline',
                   'data', 'enum', 'expect', 'external', 'final', 'infix', 'inline',
                   'inner', 'internal', 'lateinit', 'noinline', 'open', 'operator', 'out',
                   'override', 'private', 'protected', 'public', 'reified', 'sealed',
